const icon = (name, size = 18) => `<i data-lucide="${name}" style="width:${size}px;height:${size}px"></i>`;

function initIcons() {
  if (window.lucide) window.lucide.createIcons();
}

function statusBadge(value) {
  const map = {
    Live: 'success',
    Confirmed: 'success',
    Connected: 'success',
    Healthy: 'success',
    Scheduled: 'info',
    'Registration open': 'info',
    Draft: 'warning',
    'Profile incomplete': 'warning',
    Waitlisted: 'violet',
    Waitlist: 'violet',
    Failed: 'danger',
    Attention: 'danger'
  };
  return `<span class="status ${map[value] || ''}">${value}</span>`;
}

function pageHeader(title, description, actions = '') {
  return `
    <header class="page-header">
      <div>
        <h1>${title}</h1>
        ${description ? `<p>${description}</p>` : ''}
      </div>
      <div class="page-actions">${actions}</div>
    </header>
  `;
}

function metricCard(label, value, detail, iconName, tone = '') {
  return `
    <article class="metric-card">
      <div>
        <span class="metric-label">${label}</span>
        <strong>${value}</strong>
      </div>
      <span class="metric-icon ${tone}">${icon(iconName)}</span>
      <div class="metric-foot">${detail}</div>
    </article>
  `;
}

function eventRow(event) {
  const tone = event.status === 'Live' ? 'success' : event.status === 'Draft' ? 'warning' : 'info';
  const statusLabel = event.status === 'Registration open' ? 'Open' : event.status;
  return `
    <tr>
      <td>
        <div class="event-row-title">
          <span class="event-row-cover">${event.initials}</span>
          <span class="row-title">${event.name}<small>${event.type} · ${event.city}</small></span>
        </div>
      </td>
      <td>${event.date}</td>
      <td><span class="status ${tone}" title="${event.status}">${statusLabel}</span></td>
      <td>${event.registrations}</td>
      <td>
        <div style="display:grid;grid-template-columns:1fr 34px;gap:8px;align-items:center">
          <div class="progress-track"><div class="progress-bar ${event.readiness < 80 ? 'amber' : 'teal'}" style="width:${event.readiness}%"></div></div>
          <span class="cell-muted">${event.readiness}%</span>
        </div>
      </td>
      <td><button class="table-action" data-route="event-overview" aria-label="Open ${event.name}" title="Open event">${icon('arrow-right')}</button></td>
    </tr>
  `;
}

