function buyerTicketCount() {
  return Object.values(state.ticketQuantities).reduce((sum, quantity) => sum + quantity, 0);
}

function buyerSubtotal() {
  const tickets = buyerTickets.reduce((sum, ticket) => sum + ticket.price * (state.ticketQuantities[ticket.name] || 0), 0);
  const addons = buyerAddons.reduce((sum, addon) => sum + addon.price * (state.addonQuantities[addon.name] || 0), 0);
  return tickets + addons;
}

function formatAed(value) {
  return value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function buyerProgress(active) {
  return `<div class="flow-progress buyer-progress" aria-label="Buyer checkout progress">${[1,2,3,4,5].map((step, index) => `${index ? `<i class="${step <= active ? 'complete' : ''}"></i>` : ''}<span class="${step < active ? 'complete' : step === active ? 'active' : ''}">${step < active ? icon('check', 11) : step}</span>`).join('')}</div>`;
}

