function skeletonView() {
  return `<div class="page" aria-label="Loading"><div style="height:28px;width:240px;background:#e3e8ec;border-radius:5px;margin:8px 0 28px"></div><div class="metric-grid">${Array.from({ length: 4 }, () => '<div class="metric-card" style="background:#eef2f4;border-color:#eef2f4"></div>').join('')}</div><div style="height:340px;background:#eef2f4;border-radius:6px"></div></div>`;
}

function render(route = state.route, immediate = false) {
  state.route = views[route] ? route : 'home';
  const main = document.getElementById('mainContent');
  const eventContext = document.getElementById('eventContextButton');
  const eventInitials = state.eventName.split(/\s+/).slice(0, 2).map(word => word[0]).join('').toUpperCase();
  eventContext.querySelector('.event-context-mark').textContent = eventInitials;
  eventContext.querySelector('strong').textContent = state.eventName;
  eventContext.querySelector('strong').title = state.eventName;
  eventContext.querySelector('small').textContent = `${state.eventStatus} · 18 Sep 2026`;
  document.querySelectorAll('[data-route]').forEach(item => item.classList.toggle('active', item.dataset.route === state.route));
  const draw = () => {
    main.innerHTML = views[state.route]();
    main.focus({ preventScroll: true });
    initIcons();
    closeMobileNav();
  };
  if (immediate || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    draw();
  } else {
    main.innerHTML = skeletonView();
    window.setTimeout(draw, 90);
  }
  window.history.replaceState({}, '', `#${state.route}`);
}

function showToast(message) {
  const region = document.getElementById('toastRegion');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `${icon('circle-check')}<span>${message}</span><button class="table-action" aria-label="Dismiss">${icon('x', 15)}</button>`;
  region.appendChild(toast);
  initIcons();
  toast.querySelector('button').addEventListener('click', () => toast.remove());
  window.setTimeout(() => toast.remove(), 4200);
}

function openModal(content, large = false) {
  const backdrop = document.getElementById('modalBackdrop');
  const modal = document.getElementById('modal');
  modal.className = `modal ${large ? 'large' : ''}`;
  modal.innerHTML = content;
  backdrop.hidden = false;
  document.body.style.overflow = 'hidden';
  initIcons();
  modal.querySelector('button, input, select')?.focus();
}

function closeModal() {
  document.getElementById('modalBackdrop').hidden = true;
  document.body.style.overflow = '';
}

