function createEventModal() {
  const steps = ['Start', 'Event details', 'Brand & access', 'Commerce', 'Review'];
  const stepMarkup = steps.map((label, index) => {
    const number = index + 1;
    const stepClass = number === state.wizardStep ? 'active' : number < state.wizardStep ? 'complete' : '';
    return `<div class="wizard-step ${stepClass}"><span class="step-number">${number < state.wizardStep ? icon('check', 14) : number}</span><span>${label}</span></div>`;
  }).join('');
  let body = '';
  if (state.wizardStep === 1) {
    body = `<h3 class="wizard-title">Choose a starting point</h3><p class="wizard-intro">Templates carry approved structure, rules, and readiness checks.</p><div class="template-grid"><button class="template-card selected" data-template="Conference"><span class="template-thumb"></span><span class="template-copy"><strong>Conference</strong><small>Tickets, agenda, speakers, sponsors</small></span></button><button class="template-card" data-template="Field event"><span class="template-thumb green"></span><span class="template-copy"><strong>Field event</strong><small>Compact registration and check-in</small></span></button><button class="template-card" data-template="Webinar"><span class="template-thumb orange"></span><span class="template-copy"><strong>Webinar</strong><small>Live session and on-demand</small></span></button></div>`;
  } else if (state.wizardStep === 2) {
    body = `<h3 class="wizard-title">Define the event</h3><p class="wizard-intro">These details become the canonical event record.</p><div class="field"><label>Event name</label><input id="wizardName" value="${state.wizardData.name}" aria-label="Event name" /><small id="wizardNameError" style="color:var(--red);display:none">Enter an event name.</small></div><div class="field-grid"><div class="field"><label>Format</label><select id="wizardFormat" aria-label="Event format"><option>In-person</option><option>Hybrid</option><option>Virtual</option><option>Webinar</option></select></div><div class="field"><label>Timezone</label><select id="wizardTimezone" aria-label="Event timezone"><option>Asia/Dubai</option><option>Asia/Tbilisi</option><option>Europe/London</option></select></div><div class="field"><label>Start date</label><input type="date" value="2026-11-12" aria-label="Event start date" /></div><div class="field"><label>Capacity</label><input id="wizardCapacity" type="number" value="${state.wizardData.capacity}" aria-label="Event capacity" /></div></div>`;
  } else if (state.wizardStep === 3) {
    body = `<h3 class="wizard-title">Brand and access</h3><p class="wizard-intro">Configure the public identity and initial team access.</p><div class="field"><label>Primary color</label><div class="color-swatches"><button class="swatch selected" data-color="#1769aa" style="background:#1769aa" aria-label="Blue"></button><button class="swatch" data-color="#087f6b" style="background:#087f6b" aria-label="Teal"></button><button class="swatch" data-color="#80502d" style="background:#80502d" aria-label="Copper"></button><button class="swatch" data-color="#514274" style="background:#514274" aria-label="Violet"></button></div></div><div class="field"><label>Domain</label><input id="wizardDomain" value="${state.wizardData.domain}" aria-label="Event domain" /><small>Ownership will be verified before production publish.</small></div><div class="field"><label>Team access</label><label class="checkbox-row"><input id="wizardInvite" type="checkbox" checked /><span>Invite workspace event managers after creation</span></label></div>`;
  } else if (state.wizardStep === 4) {
    body = `<h3 class="wizard-title">Registration and commerce</h3><p class="wizard-intro">Start simple, then add rules and additional tiers from the event workspace.</p><div class="field"><label>Registration model</label><div class="segmented"><button class="segment">Free RSVP</button><button class="segment active">Paid tickets</button><button class="segment">Approval required</button></div></div><div class="field-grid"><div class="field"><label>Initial ticket name</label><input id="wizardTicketName" value="${state.wizardData.ticketName}" aria-label="Initial ticket name" /></div><div class="field"><label>Price in AED</label><input id="wizardTicketPrice" type="number" value="${state.wizardData.ticketPrice}" aria-label="Initial ticket price in AED" /></div></div><div class="review-item" style="margin-top:16px"><i data-lucide="credit-card"></i><span><strong>Stripe connected</strong><small style="display:block;color:var(--muted)">Test payment and signed webhooks available</small></span><span class="status success">Ready</span></div>`;
  } else {
    body = `<h3 class="wizard-title">Review and create</h3><p class="wizard-intro">A draft workspace will be provisioned with reversible defaults.</p><div class="review-list"><div class="review-item"><i data-lucide="calendar-days"></i><span><strong>${state.wizardData.name}</strong><small style="display:block;color:var(--muted)">${state.wizardData.format} · Asia/Dubai · Capacity ${state.wizardData.capacity}</small></span><button class="button small" data-wizard-jump="2">Edit</button></div><div class="review-item"><i data-lucide="palette"></i><span><strong>Northstar Events brand</strong><small style="display:block;color:var(--muted)">${state.wizardData.domain}</small></span><button class="button small" data-wizard-jump="3">Edit</button></div><div class="review-item"><i data-lucide="ticket"></i><span><strong>${state.wizardData.ticketName}</strong><small style="display:block;color:var(--muted)">AED ${state.wizardData.ticketPrice} · Hosted checkout</small></span><button class="button small" data-wizard-jump="4">Edit</button></div><div class="review-item"><i data-lucide="shield-check"></i><span><strong>Tenant isolation and audit context</strong><small style="display:block;color:var(--muted)">Inherited from Northstar Events workspace policy</small></span><span class="status success">Ready</span></div></div>`;
  }
  return `
    <div class="modal-header"><div><h2 id="modalTitle">Create event</h2><p class="panel-subtitle">Northstar Events workspace</p></div><button class="modal-close" data-action="close-modal" aria-label="Close">${icon('x')}</button></div>
    <div class="wizard-layout"><aside class="wizard-steps">${stepMarkup}</aside><div class="wizard-content">${body}</div></div>
    <div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button>${state.wizardStep > 1 ? '<button class="button" data-action="wizard-back">Back</button>' : ''}<button class="button primary" data-action="${state.wizardStep === 5 ? 'wizard-create' : 'wizard-next'}">${state.wizardStep === 5 ? 'Create draft event' : 'Continue'}${state.wizardStep < 5 ? icon('arrow-right', 15) : ''}</button></div>
  `;
}

function openCommandPalette() {
  const backdrop = document.getElementById('commandBackdrop');
  backdrop.hidden = false;
  const input = document.getElementById('commandInput');
  input.value = '';
  renderCommandResults('');
  window.setTimeout(() => input.focus(), 0);
}

function closeCommandPalette() {
  document.getElementById('commandBackdrop').hidden = true;
}

function renderCommandResults(query) {
  const items = [
    ['Future of Commerce 2026', 'Event', 'event-overview', 'calendar-days'],
    ['Partner Summit Dubai', 'Event', 'events', 'calendar-days'],
    ['Mariam Haddad', 'Attendee', 'attendees', 'contact-round'],
    ['Ticket tiers', 'Event settings', 'tickets', 'ticket'],
    ['Sending domain', 'Workspace configuration', 'communications', 'mail'],
    ['Plan & billing', 'Workspace configuration', 'billing', 'credit-card']
  ].filter(item => item[0].toLowerCase().includes(query.toLowerCase()) || item[1].toLowerCase().includes(query.toLowerCase()));
  document.getElementById('commandResults').innerHTML = items.length ? items.map(item => `<button class="command-result" data-command-route="${item[2]}"><span class="activity-icon">${icon(item[3], 15)}</span><span><strong>${item[0]}</strong><small style="display:block">${item[1]}</small></span>${icon('corner-down-left', 15)}</button>`).join('') : `<div class="empty-state" style="min-height:180px"><div><span class="empty-icon">${icon('search-x')}</span><h3>No matching records</h3><p>Try an event name, attendee, order, or setting.</p></div></div>`;
  initIcons();
}

function openMobileNav() {
  document.getElementById('sidebar').classList.add('open');
  document.getElementById('drawerBackdrop').hidden = false;
}

function closeMobileNav() {
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('drawerBackdrop').hidden = true;
}

document.addEventListener('click', event => {
  const routeTarget = event.target.closest('[data-route]');
  if (routeTarget) {
    event.preventDefault();
    closeModal();
    closeCommandPalette();
    render(routeTarget.dataset.route);
    return;
  }

  const experienceTarget = event.target.closest('[data-experience-step]');
  if (experienceTarget) {
    state.experienceStep = experienceTarget.dataset.experienceStep;
    render('experience', true);
    return;
  }

  const deviceTarget = event.target.closest('[data-experience-device]');
  if (deviceTarget) {
    state.experienceDevice = deviceTarget.dataset.experienceDevice;
    render('experience', true);
    return;
  }

  const actionTarget = event.target.closest('[data-action]');
  if (!actionTarget) return;
  const action = actionTarget.dataset.action;

  if (action === 'library-tab') {
    state.libraryTab = actionTarget.dataset.tab;
    render('templates', true);
  }
  if (action === 'builder-device') {
    state.builderDevice = actionTarget.dataset.device;
    render('website', true);
  }
  if (action === 'session-timing') {
    state.sessionTiming = actionTarget.dataset.timing;
    render(state.route === 'agenda' ? 'agenda' : 'registration', true);
    showToast(state.sessionTiming === 'during' ? 'Session choice added to registration.' : 'Session choice deferred to My Agenda.');
  }
  if (action === 'communication-tab') {
    state.communicationTab = actionTarget.dataset.tab;
    render('communications', true);
  }
  if (action === 'settings-tab') {
    state.settingsTab = actionTarget.dataset.tab;
    render('settings', true);
  }
  if (action === 'select-integration') {
    state.selectedIntegration = actionTarget.dataset.integration;
    render('integrations', true);
  }
  if (action === 'share-guest-list') showToast('Permission-scoped live attendee view created.');
  if (action === 'copy-web-checkin') showToast('Guarded web check-in link copied.');
  if (action === 'send-ops-update') showToast('Onsite update drafted for the selected live audience.');
  if (action === 'close-modal') closeModal();
  if (action === 'create-event') {
    state.wizardStep = 1;
    openModal(createEventModal(), true);
  }
  if (action === 'preview-event') openModal(eventPreviewModal(), true);
  if (action === 'publish-event') {
    if (state.eventStatus !== 'Draft') showToast('Event is already published.');
    else openModal(publishModal());
  }
  if (action === 'confirm-publish') {
    const checkbox = document.getElementById('publishConfirm');
    if (!checkbox.checked) {
      document.getElementById('publishError').style.display = 'block';
      checkbox.focus();
    } else {
      state.eventStatus = 'Scheduled';
      closeModal();
      render('event-overview', true);
      showToast('Event published. Registration is now available.');
    }
  }
  if (action === 'add-ticket') openModal(ticketModal());
  if (action === 'save-ticket') {
    closeModal();
    showToast('Ticket tier added to the draft event.');
  }
  if (action === 'create-campaign') openModal(campaignModal());
  if (action === 'save-campaign') {
    closeModal();
    showToast('Campaign created as a draft.');
  }
  if (action === 'save') showToast('Changes saved with an audit record.');
  if (action === 'change-ticket-quantity') {
    const ticket = actionTarget.dataset.ticket;
    const next = (state.ticketQuantities[ticket] || 0) + Number(actionTarget.dataset.delta);
    state.ticketQuantities[ticket] = Math.max(0, Math.min(6, next));
    render('experience', true);
  }
  if (action === 'change-addon-quantity') {
    const addon = actionTarget.dataset.addon;
    const next = (state.addonQuantities[addon] || 0) + Number(actionTarget.dataset.delta);
    state.addonQuantities[addon] = Math.max(0, Math.min(buyerTicketCount(), next));
    render('experience', true);
  }
  if (action === 'continue-to-addons') {
    state.experienceStep = 'addons';
    render('experience', true);
  }
  if (action === 'continue-to-attendees') {
    state.experienceStep = 'attendees';
    render('experience', true);
  }
  if (action === 'set-holder-mode') {
    state.holderMode = actionTarget.dataset.mode;
    render('experience', true);
  }
  if (action === 'continue-to-checkout') {
    state.experienceStep = 'checkout';
    render('experience', true);
  }
  if (action === 'toggle-terms') {
    state.termsAccepted = !state.termsAccepted;
    render('experience', true);
  }
  if (action === 'complete-payment') {
    state.orderPaid = true;
    state.experienceStep = 'order';
    render('experience', true);
    showToast('Payment approved. Ticket credentials follow each holder profile state.');
  }
  if (action === 'open-holder-completion') {
    state.experienceStep = 'completion';
    render('experience', true);
  }
  if (action === 'complete-holder-registration') {
    state.holderProfileComplete = true;
    state.experienceStep = 'credential';
    render('experience', true);
    showToast('Required profile completed and QR credential issued.');
  }
  if (action === 'review-buyer-order') {
    state.experienceStep = 'order';
    render('experience');
  }
  if (action === 'send-profile-reminder') showToast('Profile completion reminder sent to Omar Saleh.');
  if (action === 'save-session') {
    const sessionId = actionTarget.dataset.session;
    if (state.savedSessions.has(sessionId)) state.savedSessions.delete(sessionId);
    else state.savedSessions.add(sessionId);
    render('experience', true);
  }
  if (action === 'request-meeting') {
    state.networkRequested = true;
    render('experience', true);
    showToast('Meeting request sent to Daniel Okafor.');
  }
  if (action === 'vote-poll') {
    state.pollVoted = true;
    render('experience', true);
  }
  if (action === 'submit-survey') {
    state.surveySubmitted = true;
    render('experience', true);
  }
  if (action === 'restart-experience') {
    state.experienceStep = 'discover';
    state.selectedTicket = 'Executive';
    state.ticketQuantities = { 'General admission': 2, Executive: 0, 'Partner allocation': 0 };
    state.addonQuantities = { 'Workshop day': 0, 'Gala dinner': 0 };
    state.holderMode = 'later';
    state.termsAccepted = false;
    state.orderPaid = false;
    state.holderProfileComplete = false;
    state.networkRequested = false;
    state.pollVoted = false;
    state.surveySubmitted = false;
    render('experience', true);
  }
  if (['add-calendar', 'download-ticket', 'download-certificate'].includes(action)) showToast('Prototype action completed.');
  if (action === 'show-active-events') {
    state.archivedEvents = false;
    render('events', true);
  }
  if (action === 'show-archived-events') {
    state.archivedEvents = true;
    render('events', true);
  }
  if (action === 'simulate-checkin') {
    state.checkedIn += 1;
    render('onsite', true);
    showToast('Check-in recorded and badge print queued.');
  }
  if (action === 'rehearsal') showToast('Rehearsal started with offline-mode checks.');
  if (action === 'toggle') actionTarget.classList.toggle('on');
  if (action === 'select-form-block') {
    state.selectedBuilderBlock = actionTarget.dataset.block;
    render('registration', true);
  }
  if (action === 'wizard-next') {
    if (state.wizardStep === 2) {
      const name = document.getElementById('wizardName').value.trim();
      if (!name) {
        document.getElementById('wizardNameError').style.display = 'block';
        document.getElementById('wizardName').focus();
        return;
      }
      state.wizardData.name = name;
      state.wizardData.capacity = document.getElementById('wizardCapacity').value;
    }
    if (state.wizardStep === 3) state.wizardData.domain = document.getElementById('wizardDomain').value;
    if (state.wizardStep === 4) {
      state.wizardData.ticketName = document.getElementById('wizardTicketName').value;
      state.wizardData.ticketPrice = document.getElementById('wizardTicketPrice').value;
    }
    state.wizardStep += 1;
    openModal(createEventModal(), true);
  }
  if (action === 'wizard-back') {
    state.wizardStep -= 1;
    openModal(createEventModal(), true);
  }
  if (action === 'wizard-create') {
    state.eventName = state.wizardData.name;
    state.eventStatus = 'Draft';
    closeModal();
    render('event-overview', true);
    showToast('Draft event created with readiness checks.');
  }
});

document.addEventListener('click', event => {
  const template = event.target.closest('[data-template]');
  if (template) {
    document.querySelectorAll('[data-template]').forEach(item => item.classList.remove('selected'));
    template.classList.add('selected');
    state.wizardData.template = template.dataset.template;
  }
  const jump = event.target.closest('[data-wizard-jump]');
  if (jump) {
    state.wizardStep = Number(jump.dataset.wizardJump);
    openModal(createEventModal(), true);
  }
  const commandRoute = event.target.closest('[data-command-route]');
  if (commandRoute) {
    closeCommandPalette();
    render(commandRoute.dataset.commandRoute);
  }
  const swatch = event.target.closest('[data-color]');
  if (swatch) {
    document.querySelectorAll('[data-color]').forEach(item => item.classList.remove('selected'));
    swatch.classList.add('selected');
    state.wizardData.brandColor = swatch.dataset.color;
  }
});

document.getElementById('workspaceSwitcher').addEventListener('click', event => {
  event.stopPropagation();
  const menu = document.getElementById('workspaceMenu');
  menu.hidden = !menu.hidden;
});

document.addEventListener('click', event => {
  if (!event.target.closest('#workspaceSwitcher') && !event.target.closest('#workspaceMenu')) {
    document.getElementById('workspaceMenu').hidden = true;
  }
});

document.getElementById('searchButton').addEventListener('click', openCommandPalette);
document.getElementById('commandInput').addEventListener('input', event => renderCommandResults(event.target.value));
document.getElementById('commandBackdrop').addEventListener('click', event => {
  if (event.target.id === 'commandBackdrop') closeCommandPalette();
});
document.getElementById('modalBackdrop').addEventListener('click', event => {
  if (event.target.id === 'modalBackdrop') closeModal();
});
document.getElementById('menuButton').addEventListener('click', openMobileNav);
document.getElementById('drawerBackdrop').addEventListener('click', closeMobileNav);

document.addEventListener('keydown', event => {
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
    event.preventDefault();
    openCommandPalette();
  }
  if (event.key === 'Escape') {
    closeModal();
    closeCommandPalette();
    closeMobileNav();
  }
});

const initialRoute = window.location.hash.replace('#', '');
render(views[initialRoute] ? initialRoute : 'home', true);
initIcons();
